        function controls(){const busy=state.busy;$('.world-save').disabled=busy||!dirty();$('.world-reload').disabled=busy;$('#'+tool+'-map').disabled=busy;$('.world-content').inert=busy;$('.world-list-sidebar').inert=busy;}
        function touch(){state.simulation=null;controls();status(dirty()?'Unsaved changes · '+state.data.source:'Loaded '+state.data.source);renderList();if(tool==='dialogues'){drawGraph();if($('.conversation-player'))renderConversation();}if($('.rule-trace'))$('.rule-trace').replaceChildren(el('p','Rule changed. Simulate again.'));}
